/* ── Lookups ─────────────────────────────────────────────────── */

const PHOTO_BY_ID = new Map(PHOTOGRAPHS.map(p => [p.photo_id, p]));
const ALBUM_BY_ID = new Map(ALBUMS.map(a => [a.album_id, a]));
const COLLECTION_BY_ID = new Map(COLLECTIONS.map(c => [c.id, c]));

export const getPhoto = (id: string): Photo | undefined => PHOTO_BY_ID.get(id);
export const getAlbum = (id: string): Album | undefined => ALBUM_BY_ID.get(id);
export const getCollectionTitle = (id: string): string =>
  COLLECTION_BY_ID.get(id)?.title ?? "";

/** Album cover — resolved through the canonical photo record. */
export const getAlbumCover = (albumId: string): Photo | undefined => {
  const album = ALBUM_BY_ID.get(albumId);
  return album ? PHOTO_BY_ID.get(album.cover_photo_id) : undefined;
};

/** Every photograph in an album, in sequence order. */
export const getAlbumPhotos = (albumId: string): Photo[] => {
  const album = ALBUM_BY_ID.get(albumId);
  if (!album) return [];
  return album.photo_ids
    .map(id => PHOTO_BY_ID.get(id))
    .filter((p): p is Photo => Boolean(p));
};

/** Deep link to the raw folder for a collection on GitHub. */
export const collectionSourceUrl = (collectionId: string): string => {
  const first = PHOTOGRAPHS.find(p => p.collection_id === collectionId);
  if (!first) return REPO_ROOT;
  const folder = first.source_path.split("/").slice(0, 2).join("/");
  return `${REPO_ROOT}/tree/main/${encodeURI(folder)}`;
};

/** Root location of the archive. */
export const ARCHIVE_SOURCE_URL = `${REPO_ROOT}/tree/main/${encodeURI(SOURCE_DIRECTORY)}`;
